                    Text("Cup")
                }
                Button(onClick = { select(MuseumObject.ROBOT_VACUUM) }) {
                    Text("Vacuum")
                }
                Button(onClick = { select(MuseumObject.SMART_SPEAKER) }) {
                    Text("Speaker")
                }
            }

            Spacer(modifier = Modifier.height(8.dp))
            Row(horizontalArrangement = Arrangement.spacedBy(8.dp)) {
                Button(onClick = {
                    MuseumStoryStore.update(
                        if (story.isPlaying) story.pause() else story.play(),
                    )
                }) {
                    Text(if (story.isPlaying) "Pause story" else "Play story")
                }
                Button(onClick = {
                    MuseumStoryStore.update(story.restart())
                }) {
                    Text("Restart story")
                }
                Button(onClick = {
                    MuseumStoryStore.update(story.toggleReducedMotion())
                }) {
                    Text("Reduced motion: ${if (story.reducedMotion) "On" else "Off"}")
                }
            }

            Spacer(modifier = Modifier.height(8.dp))
            Row(horizontalArrangement = Arrangement.spacedBy(8.dp)) {
                Button(onClick = {
                    MuseumSelectionStore.update(MuseumSelectionStore.current.turn())
                }) {
                    Text("Turn")
                }
                Button(onClick = {
                    MuseumSelectionStore.update(MuseumSelectionStore.current.reset())
                    MuseumStoryStore.reset()
                }) {
                    Text("Reset")
